/**
 * Preservation property tests for the SkillHub encoding-char-fix.
 *
 * Spec: skillhub-encoding-char-fix (bugfix)
 * Property 2: Preservation - Already-Correct Content, Markup, and Behavior
 *             Unchanged.
 *
 * Methodology (observation-first):
 *   The pre-fix state of the whole 36-file corpus was observed on the UNFIXED
 *   files and frozen into a committed fixture,
 *   `fixtures/encoding-char-fix-baseline.json`, generated by
 *   `helpers/generate-encoding-baseline.mjs`. That snapshot records, per file:
 *     - whole-file byte identity (byteLength + sha256) for clean-file
 *       immutability,
 *     - every line's text and whether it is "clean" (contains no U+FFFD), for
 *       clean byte-range preservation,
 *     - the exact `<meta charset=...>` line, for the charset invariant.
 *
 *   These tests re-read the CURRENT on-disk files and assert they still match
 *   the frozen baseline for every input where the bug condition does NOT hold:
 *     - the 28 clean files must be byte-for-byte identical (none modified),
 *     - every clean line of the 8 affected files must be byte-identical,
 *     - the `<meta charset="UTF-8">` line and `&amp;`-style entities on clean
 *       lines must be unchanged,
 *     - locale switching, sidebar navigation, and the progress bar must behave
 *       identically (their scripts are untouched by the fix).
 *
 *   EXPECTED OUTCOME: these tests PASS on the UNFIXED code — that pass is the
 *   baseline the fix must preserve. After the per-occurrence repair, the clean
 *   files and clean lines are unchanged, so the same tests keep passing
 *   (regression guard). The baseline fixture is frozen at pre-fix state and is
 *   NOT regenerated after the fix.
 *
 * Preservation predicate (from design.md / bugfix.md):
 *   For all X where NOT isBugCondition(X): renderPage(X) = renderPage'(X)
 *
 * Validates: Requirements 3.1, 3.2, 3.3, 3.4
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fc from 'fast-check';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

import { switchLocale, LOCALE_KEY } from '../js/i18n.js';
import { renderSidebar } from '../js/navigation.js';
import { initApp } from '../js/main.js';
import { lessons } from '../js/lessons.js';

const REPLACEMENT = '\uFFFD'; // U+FFFD "�"

const __dirname = path.dirname(fileURLToPath(import.meta.url));
// skillhub/tests -> skillhub
const SKILLHUB_ROOT = path.resolve(__dirname, '..');
const BASELINE_PATH = path.resolve(
  __dirname,
  'fixtures',
  'encoding-char-fix-baseline.json',
);

/** The frozen pre-fix baseline captured from the unfixed corpus. */
const BASELINE = JSON.parse(fs.readFileSync(BASELINE_PATH, 'utf8'));

/** The exact set of files measured as affected (carry >=1 U+FFFD pre-fix). */
const EXPECTED_AFFECTED = [
  'fr/agent-anatomy-7-components.html',
  'fr/assistant-vs-agent.html',
  'fr/install-bare-metal.html',
  'fr/guardrails-5-layers.html',
  'en/agent-anatomy-7-components.html',
  'en/assistant-vs-agent.html',
  'en/install-bare-metal.html',
  'en/guardrails-5-layers.html',
].sort();

function sha256(buf) {
  return crypto.createHash('sha256').update(buf).digest('hex');
}

/**
 * Read a corpus file's raw bytes and UTF-8 text from disk by its baseline
 * relative path (e.g. "fr/assistant-vs-agent.html").
 *
 * @param {string} rel
 * @returns {{ bytes: Buffer, text: string, lines: string[] }}
 */
function readCurrent(rel) {
  const abs = path.join(SKILLHUB_ROOT, rel);
  const bytes = fs.readFileSync(abs);
  const text = bytes.toString('utf8');
  return { bytes, text, lines: text.split('\n') };
}

const ALL_RELS = Object.keys(BASELINE.files).sort();
const CLEAN_RELS = ALL_RELS.filter((rel) => !BASELINE.files[rel].affected);
const AFFECTED_RELS = ALL_RELS.filter((rel) => BASELINE.files[rel].affected);

describe('Preservation - baseline fixture integrity (pre-fix snapshot)', () => {
  it('the frozen baseline describes the expected 36-file corpus split 8 affected / 28 clean', () => {
    // Guards against a stale or mis-generated snapshot driving the comparisons.
    expect(BASELINE.generatedAtPhase).toBe('pre-fix');
    expect(BASELINE.totals.files).toBe(36);
    expect(BASELINE.totals.affected).toBe(8);
    expect(BASELINE.totals.clean).toBe(28);
    expect(ALL_RELS.length).toBe(36);
    expect(CLEAN_RELS.length).toBe(28);
    expect(AFFECTED_RELS.sort()).toEqual(EXPECTED_AFFECTED);
  });
});

describe('Preservation - Property 2: clean files are byte-for-byte immutable (Req 3.1, 3.2)', () => {
  // For every file NOT in the affected set, isBugCondition is false, so the fix
  // must not touch it at all. Drive one PBT case per clean file; a failure
  // reports the modified file as the shrunk counterexample.
  it('each of the 28 clean files matches its pre-fix bytes exactly (length + sha256 + content)', () => {
    fc.assert(
      fc.property(fc.constantFrom(...CLEAN_RELS), (rel) => {
        const base = BASELINE.files[rel];
        expect(base.affected).toBe(false);

        const { bytes, text } = readCurrent(rel);

        // Whole-file byte identity.
        expect(bytes.length).toBe(base.byteLength);
        expect(sha256(bytes)).toBe(base.sha256);
        // And still clean (no U+FFFD was ever present, must stay that way).
        expect(text.includes(REPLACEMENT)).toBe(false);
      }),
      { numRuns: CLEAN_RELS.length, verbose: true },
    );
  });

  it('the authoritative clean index pages (fr/index.html, en/index.html) are unchanged', () => {
    // These are the cross-reference sources the fix reads but must never write.
    for (const rel of ['fr/index.html', 'en/index.html']) {
      const base = BASELINE.files[rel];
      const { bytes } = readCurrent(rel);
      expect(sha256(bytes)).toBe(base.sha256);
      expect(bytes.length).toBe(base.byteLength);
    }
  });
});

describe('Preservation - Property 2: clean lines of affected files are unchanged (Req 3.1, 3.2)', () => {
  // For each affected file, every line that did NOT contain U+FFFD pre-fix is a
  // non-buggy input and must remain byte-identical after the fix. PBT drives one
  // case per (file, clean-line) pair across the full corpus of clean lines.
  const cleanLinePairs = [];
  for (const rel of AFFECTED_RELS) {
    for (const line of BASELINE.files[rel].lines) {
      if (line.clean) cleanLinePairs.push({ rel, n: line.n, text: line.text });
    }
  }

  it('enumerated enough clean lines across the affected files to be a meaningful guard', () => {
    // Sanity: the affected files are largely clean (only specific tokens are
    // corrupted), so there must be a substantial body of clean lines to protect.
    expect(cleanLinePairs.length).toBeGreaterThan(200);
  });

  it('every pre-fix clean line in the 8 affected files is byte-identical on disk', () => {
    const pairArb = fc.constantFrom(...cleanLinePairs);
    fc.assert(
      fc.property(pairArb, (pair) => {
        const current = readCurrent(pair.rel);
        // Line numbers are 1-based in the baseline.
        const currentLine = current.lines[pair.n - 1];
        // The clean line must still exist and be exactly equal (including any
        // trailing \r, entities like &amp;, tags, and attributes).
        expect(currentLine).toBe(pair.text);
        // A clean line must never gain a replacement character.
        expect(pair.text.includes(REPLACEMENT)).toBe(false);
        expect(currentLine.includes(REPLACEMENT)).toBe(false);
      }),
      { numRuns: Math.min(cleanLinePairs.length, 1000), verbose: true },
    );
  });
});

describe('Preservation - Property 2: charset declaration and clean-line markup/entities (Req 3.2, 3.3)', () => {
  it('the <meta charset="UTF-8"> line is present and byte-identical in every file', () => {
    // Req 3.3: the fix must not change the declared charset. The charset line is
    // itself clean (no U+FFFD), so it is covered by clean-line preservation too,
    // but we assert it explicitly as the stated invariant.
    for (const rel of ALL_RELS) {
      const base = BASELINE.files[rel];
      expect(base.charsetLine).not.toBe(null);
      // The declared charset is UTF-8 (ignoring the recorded trailing \r/EOL).
      expect(base.charsetLine.replace(/\r$/, '').trim()).toBe(
        '<meta charset="UTF-8">',
      );

      const current = readCurrent(rel);
      const currentCharset = current.lines.find((l) => /<meta\s+charset=/i.test(l));
      expect(currentCharset).toBe(base.charsetLine);
    }
  });

  it('entities like &amp; that live on clean lines are preserved verbatim', () => {
    // Observe every clean line carrying an HTML entity reference and assert it
    // is byte-identical on disk. This catches a clean line being accidentally
    // rewritten (e.g. &amp; mangled) by the repair.
    const entityPairs = [];
    const entityRe = /&(?:amp|lt|gt|quot|#\d+|#x[0-9a-fA-F]+|[a-zA-Z]+);/;
    for (const rel of ALL_RELS) {
      for (const line of BASELINE.files[rel].lines) {
        if (line.clean && entityRe.test(line.text)) {
          entityPairs.push({ rel, n: line.n, text: line.text });
        }
      }
    }

    // There are entity-bearing clean lines in the corpus to protect.
    expect(entityPairs.length).toBeGreaterThan(0);

    fc.assert(
      fc.property(fc.constantFrom(...entityPairs), (pair) => {
        const current = readCurrent(pair.rel);
        expect(current.lines[pair.n - 1]).toBe(pair.text);
      }),
      { numRuns: Math.min(entityPairs.length, 300) },
    );
  });
});

/**
 * Install a mock `window.location` with the given pathname that captures writes
 * to `href`, mirroring the existing i18n/navigation suites. Returns a restore
 * function.
 *
 * @param {string} pathname - The simulated current pathname.
 * @returns {() => void} restore
 */
function mockLocation(pathname) {
  const original = window.location;
  delete window.location;
  window.location = { pathname, href: '' };
  return () => {
    delete window.location;
    window.location = original;
  };
}

describe('Preservation - Property 2: interactive behavior is unchanged (Req 3.4)', () => {
  // The fix only rewrites corrupted bytes in 8 HTML files; the JS that drives
  // locale switching, navigation, and the progress bar is untouched. These
  // observations therefore hold identically before and after the fix.
  beforeEach(() => {
    document.body.innerHTML = '';
    localStorage.clear();
  });

  afterEach(() => {
    localStorage.clear();
  });

  it('locale switching persists + navigates identically for the affected-page paths', () => {
    // For each affected page in each locale, a click-equivalent switchLocale to
    // the opposite locale must swap the leading /en/ or /fr/ segment and persist
    // the normalized locale. This is the locale-switch behavior exercised on the
    // very pages the fix edits.
    const pathArb = fc.constantFrom(
      ...EXPECTED_AFFECTED.map((rel) => `/${rel}`),
    );
    const targetArb = fc.constantFrom('en', 'fr');

    fc.assert(
      fc.property(pathArb, targetArb, (pathname, target) => {
        localStorage.clear();
        const restore = mockLocation(pathname);
        try {
          switchLocale(target);
          const expectedHref = pathname.replace(/^\/(en|fr)\//, `/${target}/`);
          expect(localStorage.getItem(LOCALE_KEY)).toBe(target);
          expect(window.location.href).toBe(expectedHref);
        } finally {
          restore();
        }
      }),
      { numRuns: 100 },
    );
  });

  it('sidebar navigation marks the active lesson for every lesson pathname', () => {
    // renderSidebar wiring (grouping + active marking) is independent of the
    // corrupted bytes and must behave identically.
    const slugArb = fc.constantFrom(...lessons.map((l) => l.slug));
    fc.assert(
      fc.property(slugArb, fc.constantFrom('en', 'fr'), (slug, locale) => {
        localStorage.clear();
        localStorage.setItem(LOCALE_KEY, locale);
        const restore = mockLocation(`/${locale}/${slug}.html`);
        try {
          const container = document.createElement('div');
          renderSidebar(container, lessons, []);

          // Three track sections, exactly one active link matching the path.
          expect(container.querySelectorAll('.sidebar-section').length).toBe(3);
          const active = container.querySelectorAll('a.active');
          expect(active.length).toBe(1);
          expect(active[0].getAttribute('data-slug')).toBe(slug);
          expect(active[0].getAttribute('aria-current')).toBe('page');
        } finally {
          restore();
        }
      }),
      { numRuns: 60 },
    );
  });

  it('the progress bar paints round(complete / catalog)% for arbitrary completion sets', () => {
    // Progress-bar behavior is driven by the lesson catalog + localStorage, not
    // by the HTML byte content of the affected pages.
    const slugs = lessons.map((l) => l.slug);
    const subsetArb = fc.subarray(slugs, { minLength: 0, maxLength: slugs.length });

    fc.assert(
      fc.property(subsetArb, (completed) => {
        localStorage.clear();
        for (const slug of completed) {
          localStorage.setItem(`skillhub_lesson_complete_${slug}`, 'true');
        }
        document.body.innerHTML = `
          <div class="progress-bar-fill" style="width: 0%"></div>
          <span class="progress-percent">0%</span>
        `;

        initApp();

        const expected =
          Math.round((completed.length / lessons.length) * 100) + '%';
        expect(document.querySelector('.progress-bar-fill').style.width).toBe(
          expected,
        );
        expect(document.querySelector('.progress-percent').textContent).toBe(
          expected,
        );
      }),
      { numRuns: 60 },
    );
  });
});
